from solution import ap_sum


def test_issue_example():
    """Example asserts ap_sum(1,5,2)==25."""
    assert ap_sum(1, 5, 2) == 25  # 1+3+5+7+9 = 25


def test_issue_single_term():
    """Sum of arithmetic progression with one term equals first term."""
    assert ap_sum(7, 1, 99) == 7  # 7 = 7


def test_issue_zero_difference():
    """Sum of arithmetic progression with zero difference equals n times a."""
    assert ap_sum(3, 4, 0) == 12  # 3+3+3+3 = 12


def test_issue_empty_progression():
    """Sum of arithmetic progression with zero terms is zero."""
    assert ap_sum(5, 0, 2) == 0  # empty sum = 0


def test_issue_negative_difference():
    """Sum of arithmetic progression handles negative difference."""
    assert ap_sum(10, 4, -3) == 22  # 10+7+4+1 = 22


def test_issue_negative_first_term():
    """Sum of arithmetic progression handles negative first term."""
    assert ap_sum(-2, 3, 4) == 6  # -2+2+6 = 6


def test_issue_zero_first_term():
    """Sum of arithmetic progression starting at zero."""
    assert ap_sum(0, 3, 5) == 15  # 0+5+10 = 15


def test_issue_odd_number_of_terms():
    """Sum of arithmetic progression with odd count avoids integer-division error."""
    assert ap_sum(1, 3, 1) == 6  # 1+2+3 = 6


def test_contract_two_terms():
    """Sum of arithmetic progression with two terms equals 2a+d."""
    assert ap_sum(2, 2, 3) == 7  # 2+5 = 7


def test_contract_six_terms():
    """Sum of arithmetic progression over six terms follows AP sum."""
    assert ap_sum(5, 6, 5) == 105  # 5+10+15+20+25+30 = 105
